`timescale 1ns / 1ps

// mul_core s_h9c1so: signed 16 x 16 -> 32, H9C1-SO, OC + SC, SO output (paper) (Shi 2025).
// Reference model: approx/mulbench.py.
// Generated by python3 -m src_gan_tsmc65.approx.mulbench (do not edit).

// exponent / mantissa conversion: x (> 0) -> k = leading-one position, f = the 8
// bits after the leading one
module s_h9c1so_emc (
    input  wire [14:0] x,
    output reg  [3:0] k,
    output wire [7:0] f
);
    integer i;
    always @* begin
        k = 0;
        for (i = 1; i < 15; i = i + 1)
            if (x[i]) k = i;
    end
    wire [14:0] xs = x << (14 - k);       // leading one to bit 14
    assign f = xs[13:6];
endmodule

// mixed PWL fit of (1 + f1)(1 + f2) in units of 2^-7, sign compensated: the result is
// p1 for neg = 0 and p1 - 1 for neg = 1
module s_h9c1so_pwl (
    input  wire [7:0] f1,
    input  wire [7:0] f2,
    input  wire       neg,
    output wire [9:0] s
);
    wire [8:0] x1 = f1 + f2;
    wire signed [4:0] x2 = $signed({1'b0, f1[7:4]}) - $signed({1'b0, f2[7:4]});
    wire [3:0] ax2 = x2[4] ? -x2[3:0] : x2[3:0];
    wire [3:0] x3 = f1[7:5] + f2[7:5];
    wire [7:0] x4 = (x2[4] ? f1 : f2) & 8'b11111111;   // min(f1, f2), 8 MSBs
    wire zn1 = x3 < 4;
    wire zn5 = x3 >= 10;
    wire zn2 = ~zn1 & ~zn5 & (ax2 <= 3);
    wire zn4 = ~zn1 & ~zn5 & (ax2 >= 9);
    wire [10:0] t1 = zn5 ? {x1, 1'b0} : {1'b0, x1};
    wire [10:0] t2 = zn1 ? x4 >> 2 : zn4 ? x4 : zn5 ? -(x1 >> 4) : x1 >> 1;
    wire [10:0] bias = zn1 ? 11'd257 : zn5 ? 11'd34 : zn2 ? 11'd195 :
                        zn4 ? 11'd252 : 11'd188;
    wire [10:0] sd = t1 + t2 + bias + {9'd0, ~neg, 1'd0};   // vacant carry bit = ~sign
    assign s = sd[10:1];                      // C1: low 1 sum bit(s) dropped
endmodule

module mul_core (
    input  wire signed [15:0]  a,
    input  wire signed [15:0]  b,
    output wire signed [31:0] p
);
    // ME, one's complement: ~a[14:0] for a < 0
    wire [14:0] ma = a[15] ? ~a[14:0] : a[14:0];
    // ME, one's complement: ~b[14:0] for b < 0
    wire [14:0] mb = b[15] ? ~b[14:0] : b[14:0];
    wire [3:0] ka, kb;
    wire [7:0] fa, fb;
    s_h9c1so_emc u_ea (.x(ma), .k(ka), .f(fa));
    s_h9c1so_emc u_eb (.x(mb), .k(kb), .f(fb));
    wire neg = a[15] ^ b[15];
    wire [9:0] s;
    s_h9c1so_pwl u_pwl (.f1(fa), .f2(fb), .neg(neg), .s(s));
    // MTS: one's complement of the compensated result (= -p1 for a negative product)
    wire signed [10:0] o = {neg, s ^ {10{neg}}};
    // SHIFT: o * 2^(ka + kb - 7), arithmetic right shifts truncate
    wire [4:0] k = {1'b0, ka} + kb;              // K - 2
    wire signed [47:0] sh = $signed(o) <<< k;
    wire signed [47:0] r = sh >>> 7;
    // segment output (SO): K >= 16 keeps the upper 17 bits, else 0
    wire big = k >= 14;
    wire [31:0] v = big ? {r[31:15], 15'd0} : 32'd0;
    assign p = (~|ma | ~|mb) ? 32'sd0 : v[31:0];
endmodule
